SELECT
    ProductID, PriceDate, Price,
    FIRST_VALUE(Price) OVER (
        PARTITION BY ProductID ORDER BY PriceDate
    ) AS FirstPrice,
    LAST_VALUE(Price) OVER (
        PARTITION BY ProductID ORDER BY PriceDate
        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS LatestPrice
FROM dbo.ProductPriceHistory;

CREATE OR ALTER PROCEDURE dbo.usp_GetOrdersByCustomer
    @CustomerID INT,
    @StartDate  DATE
AS
BEGIN
    SET NOCOUNT ON;
    SELECT OrderID, OrderDate, TotalAmount
    FROM dbo.FactOrders
    WHERE CustomerID = @CustomerID
      AND OrderDate >= @StartDate
    OPTION (RECOMPILE);
END;

DECLARE @json NVARCHAR(MAX) = N'[{"sku":"A01","qty":3},{"sku":"B02","qty":5}]';

SELECT j.sku, j.qty
FROM OPENJSON(@json)
WITH (
    sku VARCHAR(20) '$.sku',
    qty INT         '$.qty'
) AS j;

DECLARE @TableName SYSNAME = N'FactOrders';
DECLARE @MinAmt DECIMAL(18,2) = 1000.00;
DECLARE @sql NVARCHAR(MAX) =
    N'SELECT TOP (100) OrderID, Amount FROM dbo.' + QUOTENAME(@TableName)
  + N' WHERE Amount >= @pMinAmt ORDER BY OrderDate DESC;';

EXEC sys.sp_executesql
    @stmt    = @sql,
    @params  = N'@pMinAmt DECIMAL(18,2)',
    @pMinAmt = @MinAmt;

SET NOCOUNT ON;
DECLARE @BatchSize INT = 5000;
WHILE 1 = 1
BEGIN
    DELETE TOP (@BatchSize)
    FROM dbo.AuditLog
    WHERE CreatedAt < DATEADD(YEAR, -3, SYSUTCDATETIME());

    IF @@ROWCOUNT < @BatchSize BREAK;
    WAITFOR DELAY '00:00:00.100';
END;

CREATE TABLE #StageSales (
    CustomerID INT NOT NULL,
    TotalAmt   DECIMAL(18, 2) NOT NULL,
    PRIMARY KEY CLUSTERED (CustomerID)
);

INSERT INTO #StageSales (CustomerID, TotalAmt)
SELECT CustomerID, SUM(Amount)
FROM dbo.FactOrders
GROUP BY CustomerID;

WITH ActiveCust AS (
    SELECT CustomerID, Region FROM dbo.DimCustomer WHERE IsActive = 1
)
SELECT Region, COUNT(*) AS Cnt FROM ActiveCust GROUP BY Region;

SELECT TOP (5) WITH TIES ProductID, SalesAmt
FROM dbo.ProductSales
ORDER BY SalesAmt DESC;

SELECT Region, YEAR(OrderDate) AS Yr, SUM(Amount) AS TotalAmt
FROM dbo.FactOrders
GROUP BY Region, YEAR(OrderDate);

SELECT o.OrderID, c.CustomerName
FROM dbo.FactOrders o
INNER JOIN dbo.DimCustomer c ON o.CustomerID = c.CustomerID;

SELECT c.CustomerID, o.OrderID, o.Amount
FROM dbo.DimCustomer c
OUTER APPLY (SELECT TOP (1) OrderID, Amount FROM dbo.FactOrders f WHERE f.CustomerID = c.CustomerID ORDER BY f.OrderDate DESC) o;

SELECT OrderID, Amount FROM dbo.Orders_2025
UNION ALL
SELECT OrderID, Amount FROM dbo.Orders_2026;

SELECT CustomerID FROM dbo.Orders_2025
INTERSECT
SELECT CustomerID FROM dbo.Orders_2026;

SELECT CustomerID FROM dbo.Orders_2025
EXCEPT
SELECT CustomerID FROM dbo.Orders_2026;

SELECT CustomerID, TotalSpend,
       NTILE(4) OVER (ORDER BY TotalSpend DESC) AS Quartile
FROM dbo.CustomerSpend;

SELECT YearMonth, Sales,
       LAG(Sales, 1, 0) OVER (ORDER BY YearMonth) AS PrevSales
FROM dbo.MonthlySales;

SELECT ProductID, PriceDate, Price,
       LAST_VALUE(Price) OVER (PARTITION BY ProductID ORDER BY PriceDate ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS EndPrice
FROM dbo.PriceHistory;

SELECT OrderID, Region, Amount,
       Amount * 100.0 / SUM(Amount) OVER (PARTITION BY Region) AS RegionSharePct
FROM dbo.FactOrders;

SELECT EmpID, Salary,
       CAST(PERCENT_RANK() OVER (PARTITION BY DeptID ORDER BY Salary) * 100 AS DECIMAL(5,1)) AS PctRank
FROM dbo.Employees;

SELECT DISTINCT DeptID,
       PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY Salary) OVER (PARTITION BY DeptID) AS MedianSalary
FROM dbo.Employees;

SELECT COALESCE(Region, N'总计') AS Region, COALESCE(Category, N'小计') AS Category, SUM(Amount) AS Amt
FROM dbo.FactSales
GROUP BY GROUPING SETS ((Region, Category), (Region), ());

SELECT Region, [2025], [2026]
FROM (SELECT Region, YEAR(OrderDate) AS Yr, Amount FROM dbo.FactOrders) s
PIVOT (SUM(Amount) FOR Yr IN ([2025], [2026])) p;

SELECT DATEADD(DAY, -7, CAST(GETDATE() AS DATE)) AS Last7Days,
       DATEDIFF(DAY, OrderDate, ShipDate) AS LeadDays
FROM dbo.FactOrders;

SELECT DATETRUNC(MONTH, OrderDate) AS MonthStart,
       EOMONTH(OrderDate) AS MonthEnd
FROM dbo.FactOrders;

SELECT JSON_VALUE(Payload, '$.user.name') AS UserName
FROM dbo.WebhookLogs
WHERE ISJSON(Payload) = 1;

MERGE dbo.DimProd WITH (HOLDLOCK) AS t USING dbo.StgProd AS s ON t.SKU = s.SKU
WHEN MATCHED THEN UPDATE SET t.Price = s.Price
WHEN NOT MATCHED THEN INSERT (SKU, Price) VALUES (s.SKU, s.Price);

SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRAN;
    UPDATE dbo.Accounts SET Balance -= 100 WHERE ID = 1;
    UPDATE dbo.Accounts SET Balance += 100 WHERE ID = 2;
    COMMIT TRAN;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRAN;
    THROW;
END CATCH;
